const Discord = require('discord.js')
const fetch = require('node-fetch')

const Commands = require('./commands')
const Utils = require('./utils')

/**
 * @typedef {Function} noPerm
 * @param {Discord.Message} message
 * @returns {any|Promise<any>}
 */

/**
 * @typedef DokdoOptions
 * @property {string[]} [aliases=['dokdo', 'dok']] Aliases of command
 * @property {string[]} [owners] ID of owners
 * @property {string} [prefix] Prefix of Bot
 * @property {any[]} [secrets=[]] Secrets to hide
 * @property {Record<string, any>} [globalVariable={}] Custom global Variable for eval
 * @property {noPerm} [noPerm] Executed when command runned by not allowed user
 * @property {boolean} [disableAttachmentExecution=false] Disable attachment execution.
 */

/**
 * @typedef MessageData
 * @property {string} [raw] Raw message content
 * @property {string} [cmd] Command
 * @property {string} [type] Command type
 * @property {string} [args] Arguments given
 */

module.exports = class Dokdo {
  /**
   * Main Client of Dokdo
   *
   * @param {Discord.Client} client Discord Client
   * @param {DokdoOptions} options Dokdo Options
   */
  constructor(
    client,
    {
      aliases = ['dokdo', 'dok'],
      owners = null,
      prefix,
      secrets = [],
      noPerm,
      disableAttachmentExecution = false,
      globalVariable = {},
      isOwner = undefined
    } = {}
  ) {
    if (!(client instanceof Discord.Client))
      throw new Error('Invalid `client`. `client` parameter is required.')
    if (noPerm && typeof noPerm !== 'function')
      throw new Error('`noPerm` parameter must be Function.')
    if (globalVariable) {
      if (typeof globalVariable !== 'object')
        throw new Error('`globalVariable` parameter must be Object.')
      else {
        Object.keys(globalVariable).forEach((el) => {
          global[el] = globalVariable[el]
        })
      }
    }

    this.owners = owners

    if (isOwner && !owners) this.owners = []

    client.once('ready', () => {
      if (!this.owners) {
        console.warn('[dokdo] Owners not given. Fetching from Application.')
        client.application.fetch().then((data) => {
          this.owners =
            data.owner.members?.map((el) => el.id) || [data.owner.id] || []
          console.info(
            `[dokdo] Fetched ${this.owners.length} owner(s): ${
              this.owners.length > 3
                ? this.owners.slice(0, 3).join(', ') +
                  ` and ${this.owners.length - 3} more owners`
                : this.owners.join(', ')
            }`
          )
        })
      }
    })

    this.client = client
    this.process = []
    this.options = {
      prefix,
      aliases,
      secrets,
      noPerm,
      disableAttachmentExecution,
      isOwner
    }
    if (!this.options.secrets || !Array.isArray(this.options.secrets))
      this.options.secrets = []
    if (!this.options.aliases) this.options.aliases = ['dokdo', 'dok']
  }

  /**
   * @param {Discord.Message} message Message
   * @returns {Promise<any>|any}
   */
  async run(message) {
    if (this.options.prefix && !message.content.startsWith(this.options.prefix))
      return

    const parsed = message.content.replace(this.options.prefix, '').split(' ')
    const codeParsed = Utils.codeBlock.parse(parsed.slice(2).join(' '))

    /**
     * @type {MessageData}
     */
    message.data = {
      raw: message.content,
      cmd: parsed[0],
      type: parsed[1],
      args: codeParsed ? codeParsed[2] : parsed.slice(2).join(' ')
    }
    if (
      !message.data.args &&
      message.attachments.size > 0 &&
      !this.options.disableAttachmentExecution
    ) {
      const file = message.attachments.first()
      const buffer = await (await fetch(file.url)).buffer()
      const type = { ext: file.name.split('.').pop(), fileName: file.name }
      if (['txt', 'js', 'ts', 'sh', 'bash', 'zsh', 'ps'].includes(type.ext)) {
        message.data.args = buffer.toString()
        if (!message.data.type && type.ext !== 'txt')
          message.data.type = type.ext
      }
    }
    if (
      this.options.aliases &&
      !this.options.aliases.includes(message.data.cmd)
    )
      return
    if (!this.owners.includes(message.author.id)) {
      let isOwner = false

      if (this.options.isOwner) {
        isOwner = await this.options.isOwner(message.author)
      }

      if (!isOwner) {
        if (this.options.noPerm) return this.options.noPerm(message)
        else return
      }
    }

    if (!message.data.type) return Commands.main(message, this)
    switch (message.data.type) {
      case 'sh':
      case 'bash':
      case 'ps':
      case 'powershell':
      case 'shell':
      case 'zsh':
      case 'exec':
        Commands.exec(message, this)
        break
      case 'js':
      case 'javascript':
        Commands.js(message, this)
        break
      case 'shard':
        Commands.shard(message, this)
        break
      case 'jsi':
        Commands.jsi(message, this)
        break
      case 'curl':
        Commands.curl(message, this)
        break
      case 'cat':
        Commands.cat(message, this)
        break
      case 'docs':
      case 'djs':
        Commands.docs(message, this)
        break
      default:
        message.channel.send(
          `Available Options: ${Object.keys(Commands)
            .map((t) => `\`${t}\``)
            .join(', ')}`
        )
    }
  }

  _addOwner(id) {
    if (this.owners.includes(id)) return
    this.owners.push(id)
    return this.owners
  }

  _removeOwner(id) {
    if (!this.owners.includes(id)) return null
    this.owners.splice(this.owners.indexOf(id), 1)
    return this.owners
  }
}

module.exports.Utils = Utils
module.exports.Commands = Commands

